const http = require('http');
const args = $input.first().json;
const query = args.query || args.q || '';
const url = 'http://host.docker.internal:3000/api/integrations/n8n/products?q=' + encodeURIComponent(query);
const data = await new Promise((resolve, reject) => {
  http.get(url, { headers: { 'x-api-key': $env.N8N_API_KEY } }, (res) => {
    let body = '';
    res.on('data', c => body += c);
    res.on('end', () => {
      try { resolve(JSON.parse(body)); }
      catch(e) { reject(new Error('JSON inválido: ' + body)); }
    });
  }).on('error', reject);
});
return JSON.stringify(data);

