const productNameFinal = productName || nameArg;
if (!productNameFinal || !prices) {
  return JSON.stringify({ error: 'Se requieren productName (o name) y prices' });
}
const bodyStr = JSON.stringify({ name: productNameFinal, prices });
const data = await new Promise((resolve, reject) => {
  const req = http.request({
    hostname: 'host.docker.internal',
    port: 3000,
    path: '/api/integrations/n8n/products',
    method: 'PATCH',
    headers: {
      'x-api-key': $env.N8N_API_KEY,
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(bodyStr)
    }
  }, (res) => {
    let body = '';
    res.on('data', c => body += c);
    res.on('end', () => {
      try { resolve(JSON.parse(body)); }
      catch(e) { reject(new Error('JSON inválido: ' + body)); }
    });
  });
  req.on('error', reject);
  req.write(bodyStr);
  req.end();
});
return JSON.stringify(data);

