const http = require('http');
const args = $input.first().json;
const { action, name, newName, isActive } = args;
if (!action || !name) {
  return JSON.stringify({ error: 'Se requieren action y name' });
}
const BASE_PATH = '/api/integrations/n8n/categories';
const makeRequest = (method, path, bodyObj) => new Promise((resolve, reject) => {
  const bodyStr = bodyObj ? JSON.stringify(bodyObj) : null;
  const headers = { 'x-api-key': $env.N8N_API_KEY };
  if (bodyStr) {
    headers['Content-Type'] = 'application/json';
    headers['Content-Length'] = Buffer.byteLength(bodyStr);
  }
  const req = http.request({
    hostname: 'host.docker.internal',
    port: 3000,
    path,
    method,
    headers
  }, (res) => {
    let body = '';
    res.on('data', c => body += c);
    res.on('end', () => {
      try { resolve(JSON.parse(body)); }
      catch(e) { reject(new Error('JSON inválido: ' + body)); }
    });
  });
  req.on('error', reject);
  if (bodyStr) req.write(bodyStr);
  req.end();
});
let data;
if (action === 'create') {
  data = await makeRequest('POST', BASE_PATH, { name });
} else if (action === 'update') {
  const body = { name };
  if (newName !== undefined) body.newName = newName;
  if (isActive !== undefined) body.isActive = isActive;
  data = await makeRequest('PUT', BASE_PATH, body);
} else if (action === 'delete') {
  data = await makeRequest('DELETE', BASE_PATH + '?name=' + encodeURIComponent(name), null);
} else {
  return JSON.stringify({ error: 'Acción desconocida: ' + action });
}
return JSON.stringify(data);
